import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FlatTreeControl } from '@angular/cdk/tree';
import { MatButtonModule } from '@angular/material/button';
import { MatIconModule } from '@angular/material/icon';
import { MatTreeFlatDataSource, MatTreeFlattener, MatTreeModule } from '@angular/material/tree';

interface FlatNode {
  id: string;
  name: string;
  expandable: boolean;
  isLoading: boolean;
  level: number;
}

@Component({
  selector: 'app-lazy-tree',
  standalone: true,
  imports: [CommonModule, MatTreeModule, MatButtonModule, MatIconModule],
  templateUrl: './lazy-tree.component.html',
})
export class LazyTreeComponent {
  private childrenByParentId = new Map<string, FlatNode[]>();

  private transformer = (node: FlatNode, level: number): FlatNode => ({ ...node, level });

  treeControl = new FlatTreeControl<FlatNode>(
    (node) => node.level,
    (node) => node.expandable,
  );

  private treeFlattener = new MatTreeFlattener(
    this.transformer,
    (node) => node.level,
    (node) => node.expandable,
    (node) => this.childrenByParentId.get(node.id),
  );

  dataSource = new MatTreeFlatDataSource(this.treeControl, this.treeFlattener);

  constructor() {
    this.dataSource.data = [
      { id: 'documents', name: 'Documents', expandable: true, isLoading: false, level: 0 },
    ];
  }

  hasChild = (_: number, node: FlatNode): boolean => node.expandable;

  toggle(node: FlatNode): void {
    if (!this.treeControl.isExpanded(node) && !this.childrenByParentId.has(node.id)) {
      node.isLoading = true;
      this.fetchChildren(node.id).then((children) => {
        this.childrenByParentId.set(node.id, children);
        node.isLoading = false;
        this.dataSource.data = this.dataSource.data;
      });
    }
    this.treeControl.toggle(node);
  }

  private fetchChildren(parentId: string): Promise<FlatNode[]> {
    return Promise.resolve([
      { id: `${parentId}-report`, name: 'Report.pdf', expandable: false, isLoading: false, level: 0 },
    ]);
  }
}
